using System;
using System.Collections;
using System.Collections.Generic;
using Astrea.BattleActions;
using Astrea.RunModifiers;
using FMODUnity;
using LittleLeo;
using LittleLeo.Events;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea.GameStates;

[CreateAssetMenu(fileName = "EndPlayerTurnState", menuName = "Data/Battle/Game States/End Player Turn State")]
public class EndPlayerTurnState : GameState
{
	[Header("Assets")]
	[SerializeField]
	private GameObjectReference playerGameObjectReference;

	[SerializeField]
	private CurrentCompanions currentCompanions;

	[SerializeField]
	private MapHandler mapHandler;

	[SerializeField]
	private VoidEvent OnPlayerBattleVictory;

	[SerializeField]
	private AstreaFirstPhaseToSecondPhaseHandler astreaFirstPhaseToSecondPhaseHandler;

	[Header("Events")]
	[SerializeField]
	private ListDiceInstanceEvent OnDiscardUsedDicesWithoutExhaustEndOfTurn;

	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[Header("SFX")]
	[SerializeField]
	private EventReference endTurnButtonSFX;

	[SerializeField]
	private EventReference discardDiceEndTurnSFX;

	[Header("Anomaly Level")]
	[SerializeField]
	private DifficultyLevel anomalyLevel;

	[Header("Hidden Anomaly Level")]
	[SerializeField]
	private GameObject hiddenAnomalyLevelTransitionBetweenBossesPrefab;

	[Header("Sea Requiem")]
	[SerializeField]
	private SeaRequiemAction seaRequiemAction;

	[Header("Debug")]
	[SerializeField]
	private bool verbose;

	[NonSerialized]
	private bool nextTurn = true;

	[NonSerialized]
	private bool init;

	[NonSerialized]
	private List<IEnumerator> endTurnActivations = new List<IEnumerator>();

	[NonSerialized]
	private bool astreaFirstPhaseDefeated;

	[NonSerialized]
	private bool calmTriggered;

	[NonSerialized]
	private bool hiddenAnomalyLevelFirstBossDefeated;

	public List<IEnumerator> EndTurnActivations => endTurnActivations;

	private bool endOfBattle
	{
		get
		{
			if (currentCorruptedAnimals.IsAnyEnemyActive())
			{
				return astreaFirstPhaseDefeated;
			}
			return true;
		}
	}

	public void SetCalmTriggered()
	{
		calmTriggered = true;
	}

	public void OnReset()
	{
		endTurnActivations.Clear();
		nextTurn = true;
		init = false;
		astreaFirstPhaseDefeated = false;
		calmTriggered = false;
		hiddenAnomalyLevelFirstBossDefeated = false;
	}

	public void OnCorruptionSourcePurged()
	{
		nextTurn = false;
		if (!mapHandler.IsOnAstreasHeart && mapHandler.CorruptionSourceBattle && ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.HiddenAnomalyLevelSecondBossPackageName != "" && !ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.HiddenAnomalyLevelFirstBossDefeatedStartBattleOnSecondBoss)
		{
			hiddenAnomalyLevelFirstBossDefeated = true;
		}
	}

	public void AstreaFirstPhaseDefeated()
	{
		astreaFirstPhaseDefeated = true;
	}

	public override void OnStartState()
	{
		base.OnStartState();
		if (!init)
		{
			ReferenceSingleton<CoroutineHandler>.Instance.Run(EndPlayerTurn());
			return;
		}
		if (endTurnActivations.Count > 0)
		{
			ActivateNextEndTurnActivation();
			return;
		}
		"No more activations".DebugLogIfVerbose(verbose);
		ReferenceSingleton<CoroutineHandler>.Instance.Run(BeforeEnemiesTurnCoroutine());
	}

	private void ActivateNextEndTurnActivation()
	{
		GameStateManager instance = ReferenceSingleton<GameStateManager>.Instance;
		"Activating Next End Turn Activation".DebugLogIfVerbose(verbose);
		("EndTurnActivations: " + endTurnActivations.Count).DebugLogIfVerbose(verbose);
		instance.ActionsQueueState.EnqueueAction(endTurnActivations.PopFirst(), ignoreNextRunActionWaitForFramesOnMobile: true);
		instance.SetState(instance.ActionsQueueState);
	}

	private IEnumerator EndPlayerTurn()
	{
		ReferenceSingleton<GameplayHandler>.Instance.SetTimeScaleSpeedBasedOnBattleSpeed();
		Debug.Log("============================== END PLAYER TURN ==================================");
		endTurnActivations.Clear();
		init = true;
		yield return InvokeAlternatives.WaitOneFrame();
		endTurnActivations.Add(ActivateEndOfTurnOmenActionsAndDiscardDiceActivation());
		if (nextTurn && currentCorruptedAnimals.activeCorruptedAnimals.Count > 0)
		{
			endTurnActivations.Add(PlayerAndCompanionsEndTurnActivation());
			if (!mapHandler.IsOnAstreasHeart && anomalyLevel.IsTargetsReceivesCorruptionDifficultyLevelActive())
			{
				endTurnActivations.Add(ActivateEndOfTurnAnomalyLevelTargetsReceiveCorruption());
			}
			endTurnActivations.Add(OnEndTurnDecreaseEffectsActivation());
		}
		else if (astreaFirstPhaseDefeated)
		{
			endTurnActivations.Add(AstreaFirstPhaseDefeatedActivation());
		}
		else if (hiddenAnomalyLevelFirstBossDefeated)
		{
			endTurnActivations.Add(HiddenAnomalyLevelFirstBossDefeated());
		}
		else if (currentCorruptedAnimals.activeCorruptedAnimals.Count == 0)
		{
			endTurnActivations.Add(BattleWonActivation());
		}
		ActivateNextEndTurnActivation();
	}

	private IEnumerator ActivateEndOfTurnOmenActionsAndDiscardDiceActivation()
	{
		if (!endOfBattle)
		{
			ReferenceSingleton<SFXHandler>.Instance.PlaySFX(endTurnButtonSFX);
		}
		if (ReferenceSingleton<PlayerDiceHandHolder>.Instance.handDices.Count > 0)
		{
			if (ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.EndOfTurnOmenCheckActivateActions.Count > 0 && !endOfBattle)
			{
				endTurnActivations.Insert(0, ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.ActivateEndOfTurnOmenActions(delegate
				{
					DiscardAllDiceFromHand();
				}));
			}
			else if (DiscardAllDiceFromHand())
			{
				yield return new WaitForSeconds(0.1f);
			}
		}
		else if (ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.EndOfTurnOmenCheckActivateActions.Count > 0 && !endOfBattle)
		{
			endTurnActivations.Insert(0, ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.ActivateEndOfTurnOmenActions(null));
		}
	}

	private IEnumerator ActivateEndOfTurnAnomalyLevelTargetsReceiveCorruption()
	{
		yield return new WaitForSeconds(0.3f);
		anomalyLevel.ActivateTargetsReceivesCorruptionDifficultyLevel();
	}

	private bool DiscardAllDiceFromHand()
	{
		List<DiceInstance> list = ReferenceSingleton<PlayerDiceHandHolder>.Instance.handDices.Duplicate();
		if (!endOfBattle)
		{
			if (!ReferenceSingleton<RunModifiersManager>.Instance.TimeDistortionRunModifier && !ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.IsPerpetualClockOmenActiveActivateAction() && !calmTriggered)
			{
				list.RemoveAll((DiceInstance diceInstance) => diceInstance.DisableDiscard);
				if (list.Count > 0)
				{
					bool num = ReferenceSingleton<PlayerDiceHandHolder>.Instance.handDices.Count > list.Count;
					CheckSeaRequiemAction(list);
					DiscardAllDiceFromHand(list);
					if (num)
					{
						ReferenceSingleton<PlayerDiceHandPositioningAnimationManager>.Instance.UpdateDiceInHandPosition();
					}
					return true;
				}
			}
			calmTriggered = false;
			return false;
		}
		DiscardAllDiceFromHand(list);
		return true;
	}

	private void DiscardAllDiceFromHand(List<DiceInstance> diceToDiscard)
	{
		if (!endOfBattle)
		{
			ReferenceSingleton<SFXHandler>.Instance.PlaySFX(discardDiceEndTurnSFX);
		}
		OnDiscardUsedDicesWithoutExhaustEndOfTurn.Raise(diceToDiscard);
	}

	private void CheckSeaRequiemAction(List<DiceInstance> diceToDiscard)
	{
		int num = 0;
		for (int i = 0; i < currentCompanions.ActiveCompanions.Count; i++)
		{
			CompanionAbility component = currentCompanions.ActiveCompanions[i].GetComponent<CompanionAbility>();
			num += component.GetSeaRequiemAmount(seaRequiemAction);
		}
		for (int j = 0; j < diceToDiscard.Count; j++)
		{
			if (diceToDiscard[j].Dice.DiceHasAction(seaRequiemAction))
			{
				num++;
			}
		}
		if (num > 0)
		{
			seaRequiemAction.AddSeaRequiem(num);
		}
	}

	private IEnumerator PlayerAndCompanionsEndTurnActivation()
	{
		bool flag = false;
		if (playerGameObjectReference.value.GetComponent<UnitEffects>().OnEndTurnEffects())
		{
			flag = true;
		}
		for (int i = 0; i < currentCompanions.ActiveCompanions.Count; i++)
		{
			if (currentCompanions.ActiveCompanions[i].GetComponent<UnitEffects>().OnEndTurnEffects())
			{
				flag = true;
			}
		}
		for (int j = 0; j < currentCorruptedAnimals.activeCorruptedAnimals.Count; j++)
		{
			if (currentCorruptedAnimals.activeCorruptedAnimals[j].GetComponent<CorruptedAnimalEffects>().EndPlayerTurnEffects())
			{
				flag = true;
			}
		}
		if (flag)
		{
			yield return new WaitForSeconds(0.3f);
		}
	}

	private IEnumerator BattleWonActivation()
	{
		OnPlayerBattleVictory.Raise();
		playerGameObjectReference.value.GetComponent<PlayerEffects>().OnEndOfBattleEffects();
		yield return new WaitForSeconds(0.5f);
	}

	private IEnumerator AstreaFirstPhaseDefeatedActivation()
	{
		playerGameObjectReference.value.GetComponent<PlayerEffects>().OnEndOfBattleEffects();
		yield return new WaitForSeconds(0.5f);
	}

	private IEnumerator HiddenAnomalyLevelFirstBossDefeated()
	{
		playerGameObjectReference.value.GetComponent<PlayerEffects>().OnEndOfBattleEffects();
		yield return new WaitForSeconds(0.5f);
	}

	private IEnumerator OnEndTurnDecreaseEffectsActivation()
	{
		for (int i = 0; i < currentCompanions.ActiveCompanions.Count; i++)
		{
			currentCompanions.ActiveCompanions[i].GetComponent<UnitEffects>().OnEndTurnDecreaseEffects();
		}
		if (playerGameObjectReference.value.GetComponent<PlayerEffects>().OnEndTurnDecreaseEffects())
		{
			yield return new WaitForSeconds(0.3f);
		}
	}

	private IEnumerator BeforeEnemiesTurnCoroutine()
	{
		init = false;
		if (astreaFirstPhaseDefeated)
		{
			yield return ReferenceSingleton<CoroutineHandler>.Instance.Run(astreaFirstPhaseToSecondPhaseHandler.AstreaFirstPhaseToSecondPhaseAnimation());
			astreaFirstPhaseDefeated = false;
			yield break;
		}
		if (hiddenAnomalyLevelFirstBossDefeated)
		{
			yield return new WaitForSeconds(0.2f);
			ReferenceSingleton<PoolHandler>.Instance.AddPool(hiddenAnomalyLevelTransitionBetweenBossesPrefab);
			ReferenceSingleton<PoolHandler>.Instance.GetObject(hiddenAnomalyLevelTransitionBetweenBossesPrefab.name).GetComponent<HiddenAnomalyLevelTransitionBetweenBosses>().Initialize();
			hiddenAnomalyLevelFirstBossDefeated = false;
			yield break;
		}
		yield return new WaitForSeconds(0.2f);
		PlayerEffects component = playerGameObjectReference.value.GetComponent<PlayerEffects>();
		if (mapHandler.CorruptionSourceBattle)
		{
			if (nextTurn)
			{
				if (!component.IsHourglassMirageTurnActive())
				{
					ReferenceSingleton<TurnManager>.Instance.StartNextTurn();
				}
				yield break;
			}
			if (!ReferenceSingleton<GameStateManager>.Instance.IsCurrentGameStateNonBattleStateAndUnlockablesStateOrEndOfBattleStateHasAlreadyBeingCalled() && ReferenceSingleton<PlayerDiceHandHolder>.Instance.handDices.Count > 0)
			{
				DiscardAllDiceFromHand();
				yield return new WaitForSeconds(0.3f);
			}
			ReferenceSingleton<GameStateManager>.Instance.TryEnterEndOfBattleStateFirstTimeOnly();
		}
		else if (currentCorruptedAnimals.activeCorruptedAnimals.Count > 0)
		{
			if (!component.IsHourglassMirageTurnActive())
			{
				ReferenceSingleton<TurnManager>.Instance.StartNextTurn();
			}
		}
		else
		{
			if (!ReferenceSingleton<GameStateManager>.Instance.IsCurrentGameStateNonBattleStateAndUnlockablesStateOrEndOfBattleStateHasAlreadyBeingCalled() && ReferenceSingleton<PlayerDiceHandHolder>.Instance.handDices.Count > 0)
			{
				DiscardAllDiceFromHand();
				yield return new WaitForSeconds(0.3f);
			}
			ReferenceSingleton<GameStateManager>.Instance.TryEnterEndOfBattleStateFirstTimeOnly();
		}
	}
}
